"""
Offline robust spline denoiser with jump isolation and conservative
prominence-based reversal removal.
"""
import numpy as np

try:
    from scipy.interpolate import UnivariateSpline
    _HAS_SPLINE = True
except Exception:
    UnivariateSpline = None
    _HAS_SPLINE = False


def _finite_signal(x):
    x = np.asarray(x, dtype=float).reshape(-1).copy()
    if x.size == 0 or np.all(np.isfinite(x)):
        return x
    good = np.flatnonzero(np.isfinite(x))
    if good.size == 0:
        return np.zeros_like(x)
    bad = np.flatnonzero(~np.isfinite(x))
    x[bad] = np.interp(bad, good, x[good])
    return x


def _fallback_smooth(x, radius):
    x = np.asarray(x, dtype=float)
    n = len(x)
    if n < 3:
        return x.copy()
    radius = max(1, min(int(radius), (n - 1) // 2))
    a = np.arange(1, radius + 2, dtype=float)
    k = np.r_[a, a[-2::-1]]
    k /= k.sum()
    p = len(k) // 2
    return np.convolve(np.pad(x, p, mode="reflect"), k, mode="valid")


def _turns(z):
    d = np.diff(z)
    if len(d) < 2:
        return np.empty(0, dtype=int)
    s = np.sign(d)
    for i in range(1, len(s)):
        if s[i] == 0:
            s[i] = s[i - 1]
    for i in range(len(s) - 2, -1, -1):
        if s[i] == 0:
            s[i] = s[i + 1]
    return np.flatnonzero(s[:-1] * s[1:] < 0) + 1


def _prune_prominent_extrema(y, z):
    y = np.asarray(y, dtype=float)
    z = np.asarray(z, dtype=float).copy()
    n = len(z)
    if n < 7:
        return z

    r = y - z
    r -= np.median(r)
    noise = 1.4826 * np.median(np.abs(r))
    span = np.percentile(y, 95) - np.percentile(y, 5)
    base = max(1.15 * noise, 0.06 * span, 1e-12)

    for _ in range(3):
        t = _turns(z)
        if len(t) == 0:
            break
        e = np.r_[0, t, n - 1]
        q = e[1:-1]
        prominence = np.minimum(np.abs(z[q] - z[e[:-2]]),
                                np.abs(z[e[2:]] - z[q]))
        width = np.minimum(q - e[:-2], e[2:] - q)
        weak = (prominence < base) | ((width <= 2) & (prominence < 2.0 * base))
        if not np.any(weak):
            break
        score = prominence / base + 0.35 * width
        j = int(np.flatnonzero(weak)[np.argmin(score[weak])]) + 1
        lo, hi = int(e[j - 1]), int(e[j + 1])
        z[lo:hi + 1] = np.linspace(z[lo], z[hi], hi - lo + 1)

    z[0], z[-1] = y[0], y[-1]
    return z


def _fit_segment(segment, sigma):
    y = np.asarray(segment, dtype=float)
    n = len(y)
    if n < 8:
        return _fallback_smooth(y, max(1, (n - 1) // 3)) if n >= 3 else y.copy()
    if not _HAS_SPLINE:
        return _fallback_smooth(y, min(4, (n - 1) // 2))

    t = np.arange(n, dtype=float)
    best = y.copy()
    best_score = np.inf
    best_factor = 1.0

    for factor in (0.15, 0.3, 0.6, 1.0, 1.7, 2.8, 4.5, 7.0):
        try:
            spl = UnivariateSpline(t, y, s=n * sigma * sigma * factor,
                                   k=min(3, n - 1))
            z = np.asarray(spl(t), dtype=float)
            if not np.all(np.isfinite(z)):
                continue
            df = len(spl.get_knots()) + len(spl.get_coeffs())
            mse = np.mean((y - z) ** 2)
            score = (mse + 1e-12) / max((1.0 - min(df / n, 0.95)) ** 2, 0.05)
            if score < best_score:
                best, best_score, best_factor = z, score, factor
        except Exception:
            pass

    for _ in range(2):
        residual = y - best
        center = np.median(residual)
        scale = max(1.4826 * np.median(np.abs(residual - center)),
                    0.25 * sigma, 1e-12)
        w = np.minimum(1.0, 2.5 * scale / (np.abs(residual - center) + 1e-12))
        w[0] = max(w[0], 0.65)
        w[-1] = max(w[-1], 0.65)
        try:
            spl = UnivariateSpline(t, y, w=w,
                                   s=n * sigma * sigma * best_factor,
                                   k=min(3, n - 1))
            candidate = np.asarray(spl(t), dtype=float)
            if np.all(np.isfinite(candidate)):
                best = candidate
        except Exception:
            break

    best[0], best[-1] = y[0], y[-1]
    return _prune_prominent_extrema(y, best)


def _full_denoise(x, window_size):
    x = _finite_signal(x)
    n = len(x)
    if n < 4:
        return x.copy()

    d = np.diff(x)
    dmed = float(np.median(d))
    dmad = float(np.median(np.abs(d - dmed))) + 1e-12
    sigma = 1.4826 * dmad / np.sqrt(2.0)
    spread = float(np.std(x)) + 1e-12

    threshold = max(6.0 * dmad, 2.5 * spread)
    cuts = np.flatnonzero(np.abs(d - dmed) > threshold) + 1
    bounds = np.r_[0, cuts, n]
    out = np.empty(n, dtype=float)

    for lo, hi in zip(bounds[:-1], bounds[1:]):
        out[lo:hi] = _fit_segment(x[lo:hi], sigma)

    return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)


def adaptive_filter(x, window_size=20):
    return enhanced_filter_with_trend_preservation(x, window_size)


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = np.asarray(x, dtype=float).reshape(-1)
    if window_size < 1:
        raise ValueError("window_size must be positive")
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return np.asarray(_full_denoise(x, window_size)[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    return enhanced_filter_with_trend_preservation(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean = (2 * np.sin(2 * np.pi * 0.5 * t)
             + 1.5 * np.sin(2 * np.pi * 2 * t)
             + 0.5 * np.sin(2 * np.pi * 5 * t)
             + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t))
    clean += 0.1 * t * np.sin(0.2 * t)
    clean += np.cumsum(rng.randn(length) * 0.05)
    return clean + rng.normal(0, noise_level, length), clean


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level
        )
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {
            "filtered_signal": filtered,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered),
        }

    clean = clean_signal[window_size - 1:]
    noisy = noisy_signal[window_size - 1:]
    m = min(len(filtered), len(clean))
    filtered, clean, noisy = filtered[:m], clean[:m], noisy[:m]

    correlation = (
        float(np.corrcoef(filtered, clean)[0, 1])
        if m > 1 and np.std(filtered) > 0 and np.std(clean) > 0 else 0.0
    )
    before = np.var(noisy - clean)
    after = np.var(filtered - clean)
    reduction = float((before - after) / before) if before > 0 else 0.0

    return {
        "filtered_signal": filtered,
        "clean_signal": clean,
        "noisy_signal": noisy,
        "correlation": correlation,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
